package org.millenaire.common.village;import java.util.*;import org.millenaire.common.utilities.*;import net.minecraft.world.item.Item;import net.minecraft.resources.ResourceLocation;public class Building{public int food;public boolean stale;public Set<String> tags=new HashSet<>();public static class Resources{public List<List<Point>> spawns=new ArrayList<>();public List<ResourceLocation> spawnTypes=new ArrayList<>();}public Resources resources=new Resources();public Resources getResManager(){return resources;}public int countGoods(Item i){return food;}public int takeGoods(Item i,int n){if(stale)return 0;int taken=Math.min(food,n);food-=taken;return taken;}public Point getPos(){return new Point();}public boolean containsTags(String t){return tags.contains(t);}}